        def _post_trust_credentials_verify_with_status(
            self, tenant: str
        ) -> None:
            # 外部凭证验真并合并状态判定：公开错误协议，任何失败都返回
            # 200 + {"valid": false, "reason": "<非空中文原因>"}。
            # 请求体须恰含 body（对象）与 signature（非空字符串），解析
